package com.hbm.machine.silex;
import com.hbm.api.machine.*;import com.hbm.energy.NodeConnection;import com.hbm.fluid.*;import com.hbm.fluid.network.*;import com.hbm.item.fluid.FluidIconItem;import com.hbm.multiblock.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;

/** Source SILEX: real external FEL illumination, peroxide material loading and deterministic isotope separation. */
public final class SilexBlockEntity extends BlockEntity implements WorldlyContainer,MenuProvider,NamedMultiblock,StandardFluidReceiver,MachineView,MuffledMachine {
 private final ItemStack[] slots=new ItemStack[11];public LaserWavelength mode=LaserWavelength.NULL;public boolean hasLaser,muffled,tilted;public final FluidTank tank=new FluidTank(HbmFluids.PEROXIDE,16000);public ItemStack current=ItemStack.EMPTY;public int currentFill,progress,recipeIndex;public static final int MAX_FILL=16000,PROCESS_TIME=100,PRIME=137;private int loadDelay;private Component customName;private FluidPorts fluidPorts;
 public SilexBlockEntity(BlockPos pos,BlockState state){super(SilexContent.ENTITY.get(),pos,state);Arrays.fill(slots,ItemStack.EMPTY);}
 @Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&DummyableBlock.isCore(state);}
 public void illuminate(LaserWavelength wavelength){mode=wavelength;}
 public static BlockPos[] networkPositions(BlockPos core,Direction facing){var side=facing.getClockWise();return new BlockPos[]{core.relative(side).above(),core.relative(side,-1).above()};}
 /** Original block marks ports relative to clicked position, while its TE network is relative to core. */
 public static BlockPos[] physicalPorts(BlockPos core,Direction facing){return networkPositions(core.relative(facing),facing);}
 @Override public Component getDisplayName(){return customName==null?Component.translatable("container.machineSILEX"):customName;}@Override public void setCustomName(Component name){customName=name;setChanged();}@Override public AbstractContainerMenu createMenu(int id,Inventory player,Player opener){return new SilexMenu(id,player,this,worldPosition);}
 public static void tick(Level level,BlockPos pos,BlockState state,SilexBlockEntity machine){if(level instanceof ServerLevel server)machine.serverTick(server);}
 private void serverTick(ServerLevel server){
  if(fluidPorts==null){var side=DummyableBlock.facing(getBlockState()).getClockWise();var positions=networkPositions(worldPosition,DummyableBlock.facing(getBlockState()));fluidPorts=new FluidPorts(positions,new NodeConnection[]{new NodeConnection(positions[0].relative(side),side),new NodeConnection(positions[1].relative(side,-1),side.getOpposite())});}fluidPorts.update(server,this);
  tank.setType(1,1,slots);tank.loadTank(2,3,slots);loadFluid();if(!process())progress=0;dequeue();if(currentFill<=0)current=ItemStack.EMPTY;setChanged();var packet=getUpdatePacket();try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<2500)player.connection.send(packet);dispatchScope.commit();}mode=LaserWavelength.NULL;
 }
 public boolean fluidConvertible(){var type=tank.getTankType();return type==HbmFluids.UF6||type==HbmFluids.PUF6||type==HbmFluids.DEATH||level!=null&&SilexRecipes.find(level.getRecipeManager(),FluidIconItem.make(type,0))!=null;}
 public void loadFluid(){
  if(fluidConvertible()){var direct=SilexRecipes.singular(FluidIconItem.make(tank.getTankType(),0));if(currentFill==0)current=direct;if(SilexRecipes.same(current,direct)){int amount=Math.min(50,Math.min(MAX_FILL-currentFill,tank.getFill()));currentFill+=amount;tank.setFill(tank.getFill()-amount);}}
  loadDelay++;if(loadDelay>20)loadDelay=0;
  if(loadDelay==0&&!slots[0].isEmpty()&&tank.getTankType()==HbmFluids.PEROXIDE&&(current.isEmpty()||SilexRecipes.same(current,slots[0]))){var recipe=SilexRecipes.find(level.getRecipeManager(),slots[0]);if(recipe==null)return;int amount=recipe.produced();if(amount<=MAX_FILL-currentFill&&amount<=tank.getFill()){currentFill+=amount;current=SilexRecipes.singular(slots[0]);tank.setFill(tank.getFill()-amount);removeItem(0,1);}}
 }
 private boolean process(){
  if(current.isEmpty()||currentFill<=0)return false;var recipe=SilexRecipes.find(level.getRecipeManager(),current);if(recipe==null||recipe.wavelength().ordinal()>mode.ordinal()||currentFill<recipe.consumed()||!slots[4].isEmpty())return false;
  progress+=(int)Math.pow(2,mode.ordinal()-recipe.wavelength().ordinal()+1)/2;
  if(progress>=PROCESS_TIME){currentFill-=recipe.consumed();int totalWeight=0;for(var choice:recipe.choices())totalWeight+=choice.weight();recipeIndex%=Math.max(totalWeight,1);int weight=0;for(var choice:recipe.choices()){weight+=choice.weight();if(recipeIndex<weight){slots[4]=choice.stack().copy();break;}}progress=0;setChanged();recipeIndex+=PRIME;}return true;
 }
 private void dequeue(){if(slots[4].isEmpty())return;for(int i=5;i<11;i++)if(!slots[i].isEmpty()&&slots[i].getCount()<slots[i].getMaxStackSize()&&ItemStack.isSameItemSameComponents(slots[4],slots[i])){slots[i].grow(1);removeItem(4,1);return;}for(int i=5;i<11;i++)if(slots[i].isEmpty()){slots[i]=slots[4].copy();slots[4]=ItemStack.EMPTY;return;}}
 public void voidContents(){currentFill=0;current=ItemStack.EMPTY;setChanged();}
 private void disconnect(){if(fluidPorts!=null&&level instanceof ServerLevel server)fluidPorts.remove(server);fluidPorts=null;}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}
 @Override public FluidTank[] getAllTanks(){return new FluidTank[]{tank};}@Override public FluidTank[] getReceivingTanks(){return getAllTanks();}@Override public boolean canConnect(HbmFluidType type,Direction side){return side!=null;}@Override public long transferFluid(HbmFluidType type,int pressure,long amount){long rejected=StandardFluidReceiver.super.transferFluid(type,pressure,amount);if(rejected!=amount)setChanged();return rejected;}
 @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}@Override public long energyStored(){return 0;}@Override public long energyCapacity(){return 0;}@Override public List<TankView> tanks(){return List.of(new TankView(tank.getTankType(),tank.getFill(),tank.getMaxFill()),new TankView("gui.hbm.silex.material",currentFill,MAX_FILL,false,0x8A8ACE));}@Override public List<ProgressView> progressBars(){return progress>0?List.of(new ProgressView("jade.hbm.silex.processing",progress,PROCESS_TIME,0x71C78B)):List.of();}
 private void writeState(CompoundTag tag,HolderLookup.Provider lookup){tank.writeToNBT(tag,"tank");tag.putInt("fill",currentFill);tag.putInt("recipeIndex",recipeIndex);tag.putString("mode",mode.name());tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);if(!current.isEmpty())tag.put("current",current.save(lookup));}
 private void readState(CompoundTag tag,HolderLookup.Provider lookup){tank.readFromNBT(tag,"tank");currentFill=tag.getInt("fill");recipeIndex=tag.getInt("recipeIndex");mode=tag.contains("mode")?LaserWavelength.valueOf(tag.getString("mode")):LaserWavelength.NULL;muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");current=currentFill>0&&tag.contains("current")?ItemStack.parseOptional(lookup,tag.getCompound("current")):ItemStack.EMPTY;}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);var list=NonNullList.withSize(11,ItemStack.EMPTY);for(int i=0;i<11;i++)list.set(i,slots[i]);ContainerHelper.saveAllItems(tag,list,lookup);writeState(tag,lookup);if(customName!=null)tag.putString("CustomName",Component.Serializer.toJson(customName,lookup));}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);var list=NonNullList.withSize(11,ItemStack.EMPTY);ContainerHelper.loadAllItems(tag,list,lookup);for(int i=0;i<11;i++)slots[i]=list.get(i);readState(tag,lookup);if(tag.contains("CustomName"))customName=Component.Serializer.fromJson(tag.getString("CustomName"),lookup);}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();writeState(tag,lookup);tag.putInt("progress",progress);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){readState(tag,lookup);progress=tag.getInt("progress");}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
 @Override public int getContainerSize(){return 11;}@Override public boolean isEmpty(){return Arrays.stream(slots).allMatch(ItemStack::isEmpty);}@Override public ItemStack getItem(int slot){return slots[slot];}@Override public ItemStack removeItem(int slot,int count){var result=slots[slot].split(count);if(!result.isEmpty())setChanged();return result;}@Override public ItemStack removeItemNoUpdate(int slot){var result=slots[slot];slots[slot]=ItemStack.EMPTY;return result;}@Override public void setItem(int slot,ItemStack stack){slots[slot]=stack;if(stack.getCount()>64)stack.setCount(64);setChanged();}@Override public void clearContent(){Arrays.fill(slots,ItemStack.EMPTY);setChanged();}@Override public boolean stillValid(Player player){return com.hbm.multiblock.SourceMachineMenuRange.isValid(this,player);}@Override public boolean canPlaceItem(int slot,ItemStack stack){return slot==0&&level!=null&&SilexRecipes.find(level.getRecipeManager(),stack)!=null;}@Override public int[] getSlotsForFace(Direction side){return new int[]{0,5,6,7,8,9,10};}@Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,Direction side){return canPlaceItem(slot,stack);}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction side){return slot>=5;}
}
